export function addQuestFlag(project,name,id){project.questFlags??=[];if(!project.questToken){const a=new Uint32Array(1);globalThis.crypto?.getRandomValues?.(a);project.questToken=a[0]||Math.floor(Math.random()*0xfffffffe)+1;}const existing=project.questFlags.find(q=>q.id===id);if(existing)return existing;const slot=project.questFlags.reduce((n,q)=>Math.max(n,q.slot+1),0);if(slot>=1024)throw Error('This project has used all 1,024 quest slots. Deleted slots remain reserved.');const q={id:id||globalThis.crypto?.randomUUID?.()||'q-'+Date.now()+'-'+slot,name:String(name||'Quest progress').slice(0,80),slot};project.questFlags.push(q);return q;}
export function validateQuests(p){if(p.questFlags===undefined)return;if(!Array.isArray(p.questFlags)||p.questFlags.length>1024)throw Error('Invalid project quest list.');if(p.questFlags.length&&(!Number.isInteger(p.questToken)||p.questToken<1||p.questToken>0xffffffff))throw Error('The quest save owner token is missing.');const ids=new Set(),slots=new Set();for(const q of p.questFlags){if(!q||typeof q.id!=='string'||ids.has(q.id)||typeof q.name!=='string'||q.name.length>80||!Number.isInteger(q.slot)||q.slot<0||q.slot>=1024||slots.has(q.slot))throw Error('A named quest flag is invalid.');ids.add(q.id);slots.add(q.slot);}}
